from z3 import Optimize, Int, Bool, If, And, Or, Implies, Sum, Not

# Helper to format minutes to human-readable 12-hour time
def fmt_time(m):
    h = (m // 60) % 24
    mi = m % 60
    ampm = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{mi:02d}{ampm}"

# Travel times (directed, in minutes)
t = {
    'Russian Hill': {
        'Sunset District': 23, 'Union Square': 10, 'Nob Hill': 5, 'Marina District': 7,
        'Richmond District': 14, 'Financial District': 11, 'Embarcadero': 8,
        'The Castro': 21, 'Alamo Square': 15, 'Presidio': 14
    },
    'Sunset District': {
        'Russian Hill': 24, 'Union Square': 30, 'Nob Hill': 27, 'Marina District': 21,
        'Richmond District': 12, 'Financial District': 30, 'Embarcadero': 30,
        'The Castro': 17, 'Alamo Square': 17, 'Presidio': 16
    },
    'Union Square': {
        'Russian Hill': 13, 'Sunset District': 27, 'Nob Hill': 9, 'Marina District': 18,
        'Richmond District': 20, 'Financial District': 9, 'Embarcadero': 11,
        'The Castro': 17, 'Alamo Square': 15, 'Presidio': 24
    },
    'Nob Hill': {
        'Russian Hill': 5, 'Sunset District': 24, 'Union Square': 7, 'Marina District': 11,
        'Richmond District': 14, 'Financial District': 9, 'Embarcadero': 9,
        'The Castro': 17, 'Alamo Square': 11, 'Presidio': 17
    },
    'Marina District': {
        'Russian Hill': 8, 'Sunset District': 19, 'Union Square': 16, 'Nob Hill': 12,
        'Richmond District': 11, 'Financial District': 17, 'Embarcadero': 14,
        'The Castro': 22, 'Alamo Square': 15, 'Presidio': 10
    },
    'Richmond District': {
        'Russian Hill': 13, 'Sunset District': 11, 'Union Square': 21, 'Nob Hill': 17,
        'Marina District': 9, 'Financial District': 22, 'Embarcadero': 19,
        'The Castro': 16, 'Alamo Square': 13, 'Presidio': 7
    },
    'Financial District': {
        'Russian Hill': 11, 'Sunset District': 30, 'Union Square': 9, 'Nob Hill': 8,
        'Marina District': 15, 'Richmond District': 21, 'Embarcadero': 4,
        'The Castro': 20, 'Alamo Square': 17, 'Presidio': 22
    },
    'Embarcadero': {
        'Russian Hill': 8, 'Sunset District': 30, 'Union Square': 10, 'Nob Hill': 10,
        'Marina District': 12, 'Richmond District': 21, 'Financial District': 5,
        'The Castro': 25, 'Alamo Square': 19, 'Presidio': 20
    },
    'The Castro': {
        'Russian Hill': 18, 'Sunset District': 17, 'Union Square': 19, 'Nob Hill': 16,
        'Marina District': 21, 'Richmond District': 16, 'Financial District': 21,
        'Embarcadero': 22, 'Alamo Square': 8, 'Presidio': 20
    },
    'Alamo Square': {
        'Russian Hill': 13, 'Sunset District': 16, 'Union Square': 14, 'Nob Hill': 11,
        'Marina District': 15, 'Richmond District': 11, 'Financial District': 17,
        'Embarcadero': 16, 'The Castro': 8, 'Presidio': 17
    },
    'Presidio': {
        'Russian Hill': 14, 'Sunset District': 15, 'Union Square': 22, 'Nob Hill': 18,
        'Marina District': 11, 'Richmond District': 7, 'Financial District': 23,
        'Embarcadero': 20, 'The Castro': 21, 'Alamo Square': 19
    }
}

# Ensure self travel time is 0 to avoid KeyError when i == j
for a, m in t.items():
    m[a] = 0

def travel(a, b):
    if a == b:
        return 0
    return t[a][b]

# Friends: index from 1..n
friends = [
    {'name': 'David',    'loc': 'Sunset District',   'start': 9*60+15,  'end': 22*60,    'min': 15},
    {'name': 'Kenneth',  'loc': 'Union Square',      'start': 21*60+15, 'end': 21*60+45, 'min': 15},
    {'name': 'Patricia', 'loc': 'Nob Hill',          'start': 15*60,    'end': 19*60+15, 'min': 120},
    {'name': 'Mary',     'loc': 'Marina District',   'start': 14*60+45, 'end': 16*60+45, 'min': 45},
    {'name': 'Charles',  'loc': 'Richmond District', 'start': 17*60+15, 'end': 21*60,    'min': 15},
    {'name': 'Joshua',   'loc': 'Financial District','start': 14*60+30, 'end': 17*60+15, 'min': 90},
    {'name': 'Ronald',   'loc': 'Embarcadero',       'start': 18*60+15, 'end': 20*60+45, 'min': 30},
    {'name': 'George',   'loc': 'The Castro',        'start': 14*60+15, 'end': 19*60,    'min': 105},
    {'name': 'Kimberly', 'loc': 'Alamo Square',      'start': 9*60,     'end': 14*60+30, 'min': 105},
    {'name': 'William',  'loc': 'Presidio',          'start': 7*60,     'end': 12*60+45, 'min': 60},
]
n = len(friends)

# Pre-map for convenience
loc_of   = {i+1: friends[i]['loc']   for i in range(n)}
start_of = {i+1: friends[i]['start'] for i in range(n)}
end_of   = {i+1: friends[i]['end']   for i in range(n)}
min_of   = {i+1: friends[i]['min']   for i in range(n)}
name_of  = {i+1: friends[i]['name']  for i in range(n)}

max_slots = n
START_LOC = 'Russian Hill'
START_TIME = 9*60  # 9:00 AM

opt = Optimize()

used  = [Bool(f"used_{p}")   for p in range(max_slots)]
who   = [Int(f"who_{p}")     for p in range(max_slots)]
start = [Int(f"start_{p}")   for p in range(max_slots)]
dur   = [Int(f"dur_{p}")     for p in range(max_slots)]

# Domains and basic relations
for p in range(max_slots):
    opt.add(who[p] >= 0, who[p] <= n)
    opt.add(start[p] >= 0)
    opt.add(dur[p] >= 0)
    # used <-> who != 0, and zero time when unused
    opt.add(Implies(used[p], who[p] != 0))
    opt.add(Implies(who[p] == 0, Not(used[p])))
    opt.add(Implies(Not(used[p]), And(start[p] == 0, dur[p] == 0)))

# Prefix usage
for p in range(1, max_slots):
    opt.add(Implies(used[p], used[p-1]))

# Time windows and minimum durations per slot/friend
for p in range(max_slots):
    for i in range(1, n+1):
        opt.add(Implies(who[p] == i, And(
            start[p] >= start_of[i],
            start[p] + dur[p] <= end_of[i],
            dur[p] >= min_of[i]
        )))

# Travel from start to first slot
if max_slots > 0:
    p = 0
    for i in range(1, n+1):
        opt.add(Implies(who[p] == i, start[p] >= START_TIME + travel(START_LOC, loc_of[i])))

# Travel between consecutive slots
for p in range(1, max_slots):
    for i in range(1, n+1):
        for j in range(1, n+1):
            tt = travel(loc_of[i], loc_of[j])
            opt.add(Implies(And(who[p-1] == i, who[p] == j),
                            start[p] >= start[p-1] + dur[p-1] + tt))

# Each friend at most once
for i in range(1, n+1):
    opt.add(Sum([If(who[p] == i, 1, 0) for p in range(max_slots)]) <= 1)

# Objective: maximize number of used slots (i.e., number of friends met)
total_meetings = Sum([If(used[p], 1, 0) for p in range(max_slots)])
opt.maximize(total_meetings)

res = opt.check()
if str(res) != 'sat':
    print("[]")
else:
    model = opt.model()
    # Extract ordered plan
    plan = []
    # Start message
    plan.append(f"You start at {START_LOC} at {fmt_time(START_TIME)}.")
    prev_loc = START_LOC
    prev_end = START_TIME

    for p in range(max_slots):
        if model.evaluate(used[p]).is_true():
            idx = model.evaluate(who[p]).as_long()
            loc = loc_of[idx]
            name = name_of[idx]
            s = model.evaluate(start[p]).as_long()
            d = model.evaluate(dur[p]).as_long()
            e = s + d
            travel_time = travel(prev_loc, loc)
            arrival = prev_end + travel_time

            plan.append(f"You travel to {loc} in {travel_time} minutes and arrive at {fmt_time(arrival)}.")
            if s > arrival:
                plan.append(f"You wait until {fmt_time(s)}.")
            plan.append(f"You meet {name} for {d} minutes from {fmt_time(s)} to {fmt_time(e)}.")

            prev_loc = loc
            prev_end = e
        else:
            break

    print(plan)
